(function(E){ const x = E["hr-m6"] = E["hr-m6"] || {units:{}}; x.units["hr-6-1"] = {"explain":{"id":"c-hr-6-1-e","course":"hr","unit":"hr-6-1","type":"explain","level":"B1","title":{"en":"Explaining a package","tr":"Bir ücret paketini açıklamak","fa":"توضیح بسته‌ی حقوق و مزایا"},"objective":{"en":"After this lesson, you can explain pay and benefits clearly: the total first, then the parts, with the right numbers.","tr":"Bu dersin sonunda maaşı ve yan hakları net biçimde açıklayabileceksin: önce toplam, sonra kalemler, doğru rakamlarla.","fa":"بعد از این درس می‌توانی حقوق و مزایا را روشن توضیح بدهی: اول جمع کل، بعد اجزا، با عددهای درست."},"hook":{"en":"Say the total first, then the parts. A confusing pay talk can lead someone to choose the wrong offer. Hana compared basic salaries and nearly chose the wrong offer. Leyla started with the total, then the parts.","tr":"Önce toplamı, sonra parçaları söyle. Karışık bir maaş konuşması birinin yanlış teklifi seçmesine yol açabilir. Hana temel maaşları karşılaştırdı ve neredeyse yanlış teklifi seçiyordu. Leyla önce toplamla, sonra kalemlerle başladı.","fa":"اول جمع کل را بگو و بعد بخش‌ها را. توضیح گیج‌کننده درباره‌ی حقوق ممکن است باعث شود کسی پیشنهاد اشتباه را انتخاب کند. هانا حقوق پایه را مقایسه کرد و نزدیک بود پیشنهاد اشتباه را انتخاب کند. لیلا از مبلغ کل شروع کرد و بعد سراغ اجزا رفت."},"before":{"en":"Explain a pay package to a new hire in two or three sentences: the total first, then each part.","tr":"Yeni işe alınan birine bir maaş paketini iki üç cümleyle anlat: önce toplam, sonra her bir kalem.","fa":"یک بسته‌ی حقوق و مزایا را در دو سه جمله برای یک استخدامی تازه توضیح بده: اول جمع کل، بعد هر بخش."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Total first, then the parts","tr":"Önce toplam, sonra parçalar","fa":"اول جمع کل و بعد بخش‌ها"},"body":{"en":"The parts only make sense after the total. So give the total, then name each part.","tr":"Parçalar ancak toplamdan sonra anlam kazanır. Bu yüzden toplamı ver, sonra her parçanın adını söyle.","fa":"بخش‌ها فقط بعد از جمع کل معنی پیدا می‌کنند. پس جمع کل را بگو و بعد هر بخش را نام ببر."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Talking about pay: rise by / to, per cent, a month","tr":"Maaştan bahsetmek: rise by / to, per cent, a month","fa":"حرف زدن از حقوق: rise by / to، درصد، ماهانه"},"steps":[{"en":"Size of the change: by. New level: to.","tr":"Değişimin büyüklüğü: by. Yeni düzey: to.","fa":"برای اندازه‌ی تغییر by می‌آید و برای سطح جدید to.","ex":"rises by 5% to 8,400 dirhams"},{"en":"per cent never takes -s.","tr":"per cent asla -s almaz.","fa":"⁨per cent⁩ هیچ‌وقت ⁨-s⁩ نمی‌گیرد.","ex":"80 per cent of the cost"},{"en":"How often: a month or per month, not in month.","tr":"Ne sıklıkla: a month ya da per month; in month değil.","fa":"برای اینکه بگویی هر چند وقت، a month یا per month بگو، نه in month.","ex":"3,000 dirhams a month"},{"en":"Total first, then the parts.","tr":"Önce toplam, sonra kalemler.","fa":"اول مبلغ کل را بگو، بعد اجزا را.","ex":"Your total package is 11,800 dirhams a month: ..."}],"table":{"headers":{"en":["Meaning","Example"],"tr":["Anlam","Örnek"],"fa":["معنی","مثال"]},"rows":[["size of change","Your basic salary rises by 5% after one year."],["new level","It rises to 8,400 dirhams a month."],["part of a whole","Insurance covers 80 per cent of the cost."],["how often","The housing allowance is 3,000 dirhams a month."]]},"tip":{"en":"Turkish '%5 artar' and Persian '5 darsad ziad mishe' need no preposition, so learners guess with or of. English uses by for the change and to for the result.","tr":"Türkçede '%5 artar' derken edat kullanılmaz; bu yüzden with ya da of tahmin edilir. İngilizcede değişim için by, sonuç için to kullanılır.","fa":"در فارسی می‌گوییم «۵ درصد زیاد می‌شود» و حرف اضافه‌ای لازم نیست؛ برای همین بعضی‌ها with یا of حدس می‌زنند. در انگلیسی برای اندازه‌ی تغییر by و برای نتیجه to می‌آید."},"wrong":"Your basic salary rises with 5% after one year.","right":"Your basic salary rises by 5% after one year."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Let me start with the total, then the parts.","meaning":{"en":"Organises the numbers.","tr":"Sayıları düzenler.","fa":"عددها را مرتب و قابل فهم می‌کند."}},{"phrase":"...rises by 5% to...","meaning":{"en":"Gives the change and the new level.","tr":"Değişimi ve yeni seviyeyi verir.","fa":"مقدار تغییر و سطح جدید را می‌گوید."}},{"phrase":"To be fair to you, ...","meaning":{"en":"Introduces an honest point that may not help you.","tr":"Kendi aleyhine olabilecek dürüst bir noktayı başlatır.","fa":"نکته‌ای صادقانه را مطرح می‌کند که شاید به نفع خودت یا شرکتت نباشد."}},{"phrase":"package","meaning":{"en":"Everything you get: salary, allowances and benefits.","tr":"ücret paketi.","fa":"بسته‌ی حقوق و مزایا (حقوق، کمک‌هزینه‌ها و مزایا روی هم)"}},{"phrase":"allowance","meaning":{"en":"Extra money for a special purpose, like housing or transport.","tr":"yan ödeme, yardım (ör. konut yardımı, yol yardımı).","fa":"کمک‌هزینه؛ «حق» (مثل حق مسکن یا حق ایاب‌وذهاب)"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Gross, net or basic: say which","tr":"Brüt mü, net mi, temel mi: hangisi olduğunu söyle","fa":"ناخالص، خالص یا پایه؟ بگو کدام"},"body":{"en":"Pay is talked about differently in different places. In the UAE, packages are usually split into basic salary and allowances, there is no personal income tax, and the end-of-service gratuity is calculated on basic salary only. In the UK, people usually quote gross pay per year. In Turkey, people often talk about net pay per month. Always say which one you mean.","tr":"Maaştan farklı yerlerde farklı biçimde bahsedilir. BAE'de paketler genellikle temel maaş ve yan ödemeler olarak bölünür, kişisel gelir vergisi yoktur ve kıdem tazminatı yalnızca temel maaş üzerinden hesaplanır. Birleşik Krallık'ta insanlar genellikle yıllık brüt maaşı söyler. Türkiye'de çoğu zaman aylık net maaştan bahsedilir. Hangisini kastettiğini her zaman söyle.","fa":"در هر جای دنیا جور دیگری درباره‌ی حقوق حرف می‌زنند. در امارات، بسته معمولاً به حقوق پایه و کمک‌هزینه‌ها تقسیم می‌شود، مالیات بر درآمد شخصی وجود ندارد و مزایای پایان خدمت فقط بر اساس حقوق پایه حساب می‌شود. در بریتانیا معمولاً حقوق ناخالص سالانه را می‌گویند. در ترکیه بیشتر از حقوق خالص ماهانه حرف می‌زنند (در ایران هم معمولاً همین‌طور است). همیشه روشن کن منظورت کدام است."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از بخش‌های پراکنده تا اول جمع کل"},"text":"Facts: Total: 9,000 a month. Basic 6,000, housing 2,500, transport 500.","item":"Basic is 6,000, then there's housing, and maybe transport too.","why":{"en":"Weak: parts with no total. Strong: total, then parts.","tr":"Zayıf: toplamı olmayan parçalar. Güçlü: toplam, sonra parçalar.","fa":"نسخه‌ی اول بخش‌ها را بدون جمع کل می‌گوید. نسخه‌ی دوم اول جمع کل را می‌گوید و بعد بخش‌ها را."},"answer":"Your total is 9,000 a month: 6,000 basic, 2,500 housing and 500 transport.","cut":["and maybe transport too"],"cutHint":{"en":"Tap the vague part a new hire cannot plan with.","tr":"Yeni işe alınanın plan yapamayacağı belirsiz kısma dokun.","fa":"روی بخش مبهمی بزن که استخدامی تازه نمی‌تواند با آن برنامه‌ریزی کند."}},"quick":{"prompt":"A candidate in Istanbul and one in London both ask: \"What is the salary?\" What should you always add?","options":["Whether it is gross or net, and per month or per year","The salary of the last person in the role","Nothing: a number is enough"],"correct":0,"why":{"en":"Say gross or net, and per month or per year: in the UK people quote gross pay per year, and in Turkey net pay per month.","tr":"Brüt mü net mi, aylık mı yıllık mı olduğunu söyle: İngiltere’de insanlar genellikle yıllık brüt maaştan, Türkiye’de ise aylık net maaştan söz eder.","fa":"بگو ناخالص است یا خالص و ماهانه است یا سالانه: در انگلیس معمولاً حقوق ناخالص سالانه را می‌گویند و در ترکیه حقوق خالص ماهانه را."},"point":4},"remember":{"en":"Point at the number after the word. Is it a change (5%)? by. Is it where you end up (8,400)? to. Result of this lesson: you can explain an offer clearly. You also have an offer summary.","tr":"Kelimeden sonraki sayıyı göster. Bir değişim mi (%5)? by. Ulaşılan düzey mi (8.400)? to. Bu dersin sonucu: bir teklifi net biçimde açıklayabilirsin ve elinde bir teklif özeti olur.","fa":"به عددِ بعد از کلمه نگاه کن. تغییر است (۵ درصد)؟ by. سطحی است که به آن می‌رسی (۸٬۴۰۰)؟ ⁨to⁩. حالا می‌توانی پیشنهاد کار را روشن توضیح بدهی. خلاصه‌ی پیشنهاد هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Comparing offers: the longer..., the more...; twice as many as","tr":"Teklifleri karşılaştırmak: the longer..., the more...; twice as many as","fa":"مقایسه‌ی پیشنهادها: the longer..., the more...؛ twice as many as"},"steps":[{"en":"Grows together: the + comparative..., the + comparative.","tr":"Birlikte artan: the + karşılaştırma..., the + karşılaştırma.","fa":"وقتی دو چیز با هم رشد می‌کنند، هر دو بخش جمله با the و صفت تفضیلی شروع می‌شوند.","ex":"The longer you stay, the higher your gratuity."},{"en":"Multiples: twice / three times as ... as.","tr":"Katlar: twice / three times as ... as.","fa":"برای چند برابر، twice یا three times as ... as را به کار ببر.","ex":"twice as many people as theirs"},{"en":"many + countable, much + uncountable.","tr":"many + sayılabilen, much + sayılamayan.","fa":"many با اسم شمارش‌پذیر می‌آید و much با اسم شمارش‌ناپذیر.","ex":"twice as many days / twice as much leave"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["the + comparative, the + comparative","The longer you stay, the higher your gratuity."],["twice as many + countable + as","Our insurance covers twice as many people as theirs."],["three times as much + uncountable + as","three times as much training budget as last year"]]},"body":{"en":"B2 track: in your speaking or email, compare the two offers once with \"the ..., the ...\" and once with \"twice as ... as\".","tr":"B2 yolu: konuşmanda ya da e-postanda iki teklifi bir kez \"the ..., the ...\" ile, bir kez \"twice as ... as\" ile karşılaştır.","fa":"مسیر B2: در صحبت یا ایمیلت، دو پیشنهاد را یک بار با «⁨the ..., the ...⁩» و یک بار با «twice as ... as» مقایسه کن."}},"source":{"en":"Gratuity facts from UAE Federal Decree-Law No. 33 of 2021.","tr":"Kıdem tazminatı bilgileri BAE’nin 2021 tarihli ve 33 sayılı Federal Kanun Hükmünde Kararnamesi’nden alınmıştır.","fa":"اطلاعات مزایای پایان خدمت از فرمان-قانون فدرال شماره‌ی ۳۳ سال ۲۰۲۱ امارات."}},"grammar":{"id":"c-hr-6-1-g","level":"B1","course":"hr","unit":"hr-6-1","title":"Talking about pay: rise by / to, per cent, a month","titleTr":"Maaştan bahsetmek: rise by / to, per cent, a month","exp":{"en":"Explaining a package is mostly numbers, and three small words cause most errors. By gives the size of a change; to gives the new level: \"Your basic salary rises by 5% after one year.\" (the change) and \"It rises to 8,400 dirhams.\" (the new number). Per cent never takes -s: \"80 per cent\", not \"80 percents\" (percentage is the noun without a number: \"a high percentage\"). For how often, use a or per, not in: \"3,000 dirhams a month\" or \"per month\", not \"in month\". Say the total first, then the parts, so the listener is not lost in numbers.","tr":"Bir ücret paketini açıklamak çoğunlukla sayılardan oluşur ve hataların çoğuna üç küçük sözcük neden olur. By değişimin büyüklüğünü, to yeni seviyeyi verir: \"Your basic salary rises by 5% after one year.\" (değişim) ve \"It rises to 8,400 dirhams.\" (yeni sayı). Per cent asla -s almaz: \"80 per cent\"; \"80 percents\" değil (percentage sayısız kullanılan isimdir: \"a high percentage\"). Ne sıklıkla olduğunu söylemek için in değil, a ya da per kullan: \"3,000 dirhams a month\" ya da \"per month\"; \"in month\" değil. Dinleyen sayılar arasında kaybolmasın diye önce toplamı, sonra parçaları söyle.","fa":"توضیح بسته‌ی حقوق و مزایا بیشتر با عدد سروکار دارد، و سه کلمه‌ی کوچک بیشترین خطاها را می‌سازند. ⁨by⁩ مقدار تغییر را نشان می‌دهد و ⁨to⁩ سطح جدید را: «⁨Your basic salary rises by 5% after one year.⁩» (یعنی «پنج درصد افزایش پیدا می‌کند») و «⁨It rises to 8,400 dirhams.⁩» (یعنی «به ۸٬۴۰۰ درهم می‌رسد»). ⁨per cent⁩ هیچ‌وقت ⁨-s⁩ نمی‌گیرد: «⁨80 per cent⁩»، نه «⁨80 percents⁩». (⁨percentage⁩ اسمی است که بدون عدد می‌آید: «⁨a high percentage⁩».) برای «در هر ماه» یا «در هر سال» از ⁨a⁩ یا ⁨per⁩ استفاده کن، نه ⁨in⁩: «⁨3,000 dirhams a month⁩» یا «⁨per month⁩»، نه «⁨in month⁩». یک توصیه‌ی کاربردی: اول جمع کل را بگو و بعد اجزا را، تا شنونده میان عددها گم نشود."},"formsTable":{"headers":{"en":["Meaning","Example"],"tr":["Anlam","Örnek"],"fa":["معنی","مثال"]},"rows":[["size of change","Your basic salary rises by 5% after one year."],["new level","It rises to 8,400 dirhams a month."],["part of a whole","Insurance covers 80 per cent of the cost."],["how often","The housing allowance is 3,000 dirhams a month."]]},"wrong":"The allowance is 3,000 dirhams in month.","right":"The allowance is 3,000 dirhams a month.","blank":{"sentence":"Your basic salary rises ___ 5% after one year.","word":"by","distractors":["with","of"]},"wrong2":"Health insurance covers 80 percents of the cost.","right2":"Health insurance covers 80 per cent of the cost.","blank2":{"sentence":"Health insurance covers 80 ___ of the cost for your family.","word":"per cent","distractors":["percents","percentage"]},"expParts":{"tryFrom":"blank","hook":{"en":"Hana compared basic salaries and nearly chose the wrong offer. Leyla started with the total, then the parts.","tr":"Hana temel maaşları karşılaştırdı ve neredeyse yanlış teklifi seçiyordu. Leyla önce toplamla, sonra kalemlerle başladı.","fa":"هانا حقوق پایه را مقایسه کرد و نزدیک بود پیشنهاد اشتباه را انتخاب کند. لیلا از مبلغ کل شروع کرد و بعد سراغ اجزا رفت."},"tryWhy":{"en":"by: by gives the size of the change (5%). to would give the new level (8,400).","tr":"by: by değişimin büyüklüğünü verir (%5). to ise yeni düzeyi verir (8.400).","fa":"جواب by است: اندازه‌ی تغییر را نشان می‌دهد (۵ درصد). to سطح جدید را نشان می‌دهد (۸٬۴۰۰)."},"rule":[{"en":"Size of the change: by. New level: to.","tr":"Değişimin büyüklüğü: by. Yeni düzey: to.","fa":"برای اندازه‌ی تغییر by می‌آید و برای سطح جدید to.","ex":"rises by 5% to 8,400 dirhams"},{"en":"per cent never takes -s.","tr":"per cent asla -s almaz.","fa":"⁨per cent⁩ هیچ‌وقت ⁨-s⁩ نمی‌گیرد.","ex":"80 per cent of the cost"},{"en":"How often: a month or per month, not in month.","tr":"Ne sıklıkla: a month ya da per month; in month değil.","fa":"برای اینکه بگویی هر چند وقت، a month یا per month بگو، نه in month.","ex":"3,000 dirhams a month"},{"en":"Total first, then the parts.","tr":"Önce toplam, sonra kalemler.","fa":"اول مبلغ کل را بگو، بعد اجزا را.","ex":"Your total package is 11,800 dirhams a month: ..."}],"test":{"en":"Point at the number after the word. Is it a change (5%)? by. Is it where you end up (8,400)? to.","tr":"Kelimeden sonraki sayıyı göster. Bir değişim mi (%5)? by. Ulaşılan düzey mi (8.400)? to.","fa":"به عددِ بعد از کلمه نگاه کن. تغییر است (۵ درصد)؟ by. سطحی است که به آن می‌رسی (۸٬۴۰۰)؟ ⁨to⁩."},"contrast":{"en":"Turkish '%5 artar' and Persian '5 darsad ziad mishe' need no preposition, so learners guess with or of. English uses by for the change and to for the result.","tr":"Türkçede '%5 artar' derken edat kullanılmaz; bu yüzden with ya da of tahmin edilir. İngilizcede değişim için by, sonuç için to kullanılır.","fa":"در فارسی می‌گوییم «۵ درصد زیاد می‌شود» و حرف اضافه‌ای لازم نیست؛ برای همین بعضی‌ها with یا of حدس می‌زنند. در انگلیسی برای اندازه‌ی تغییر by و برای نتیجه to می‌آید."}},"errorWatch":[{"find":["percents","per cents","dirhams in month","in month"],"fix":{"en":"Say 'per cent' with no -s, and 'a month' or 'per month': '3,000 dirhams a month'.","tr":"'per cent'i -s olmadan, sıklık için 'a month' ya da 'per month' kullan: '3,000 dirhams a month'.","fa":"بنویس «⁨per cent⁩» بدون ⁨-s⁩، و «⁨a month⁩» یا «⁨per month⁩»: «⁨3,000 dirhams a month⁩»."}},{"find":["rises with","rise with","increases with","goes up with","rises of"],"fix":{"en":"Use by for the size of the change: 'rises by 5%'.","tr":"Değişimin büyüklüğü için by kullan: 'rises by 5%'.","fa":"برای اندازه‌ی تغییر by بنویس: «rises by 5%»."}}]},"b2":{"id":"c-hr-6-1-b2","level":"B2","track":"B2","course":"hr","unit":"hr-6-1","title":"Comparing offers: the longer..., the more...; twice as many as","titleTr":"Teklifleri karşılaştırmak: the longer..., the more...; twice as many as","exp":{"en":"Two comparison patterns are very useful for explaining a package. The double comparative shows that one thing grows with another: \"The longer you stay, the higher your gratuity.\" Both halves need the: \"The longer..., the more...\", not \"More you stay, more you get\". Multiples use as ... as: \"Our insurance covers twice as many people as theirs.\", \"three times as much leave\". Use many with countable nouns (people, days) and much with uncountable ones (money, leave). Avoid \"two times more as\" and \"twice more than\" in formal writing.","tr":"Bir paketi açıklamak için iki karşılaştırma kalıbı çok yararlıdır. Çift karşılaştırma, bir şeyin başka bir şeyle birlikte arttığını gösterir: \"The longer you stay, the higher your gratuity.\" İki yarıda da the gerekir: \"The longer..., the more...\"; \"More you stay, more you get\" değil. Türkçedeki \"ne kadar uzun kalırsan, o kadar fazla\" yapısına benzer. Katlar için as ... as kullanılır: \"Our insurance covers twice as many people as theirs.\", \"three times as much leave\". Sayılabilen isimlerle (people, days) many, sayılamayanlarla (money, leave) much kullan. Resmî yazıda \"two times more as\" ve \"twice more than\" kullanmaktan kaçın.","fa":"دو الگوی مقایسه برای توضیح یک بسته خیلی به کار می‌آید. مقایسه‌ی دوگانه نشان می‌دهد چیزی همراه با چیز دیگر زیاد می‌شود؛ درست مثل «هرچه... ، ...تر» در فارسی: «⁨The longer you stay, the higher your gratuity.⁩» یعنی «هرچه بیشتر بمانید، مزایای پایان خدمتتان بیشتر می‌شود». هر دو نیمه the لازم دارند: «⁨The longer..., the more...⁩»، نه «More you stay, more you get». برای «چند برابر» از as ... as استفاده می‌شود: «⁨Our insurance covers twice as many people as theirs.⁩» و «three times as much leave». با اسم‌های قابل‌شمارش (people، days) از many و با اسم‌های غیرقابل‌شمارش (money، leave) از much استفاده کن. در نوشته‌ی رسمی از «two times more as» و «twice more than» پرهیز کن."},"formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["the + comparative, the + comparative","The longer you stay, the higher your gratuity."],["twice as many + countable + as","Our insurance covers twice as many people as theirs."],["three times as much + uncountable + as","three times as much training budget as last year"]]},"wrong":"More you stay, more you get.","right":"The longer you stay, the more you get.","blank":{"sentence":"The longer you stay, ___ your gratuity.","word":"the higher","distractors":["higher","the highest"]},"wrong2":"Our insurance covers two times more people as theirs.","right2":"Our insurance covers twice as many people as theirs.","blank2":{"sentence":"Our health insurance covers twice as ___ family members as theirs.","word":"many","distractors":["much","more"]},"useIn":{"en":"B2 track: in your speaking or email, compare the two offers once with \"the ..., the ...\" and once with \"twice as ... as\".","tr":"B2 yolu: konuşmanda ya da e-postanda iki teklifi bir kez \"the ..., the ...\" ile, bir kez \"twice as ... as\" ile karşılaştır.","fa":"مسیر B2: در صحبت یا ایمیلت، دو پیشنهاد را یک بار با «⁨the ..., the ...⁩» و یک بار با «twice as ... as» مقایسه کن."},"exitItem":{"from":"hr-6-1","kind":"blank","prompt":"The more routes you learn, ___ your bonus.","options":["bigger","the bigger","the biggest"],"correct":1,"why":{"en":"the bigger: 'the more ..., the + comparative'. 'Bigger' drops the second 'the', and 'the biggest' is a superlative.","tr":"the bigger: 'the more ..., the + karşılaştırma sıfatı'. 'Bigger' ikinci 'the'yi düşürür; 'the biggest' en üstünlük biçimidir.","fa":"the bigger درست است، چون الگو the more ..., the و صفت تفضیلی است. bigger بدون the دوم است و the biggest صفت عالی است."}},"expParts":{"hook":{"en":"'The longer you stay, the higher your gratuity.' One sentence that tells Hana the honest trade-off.","tr":"'The longer you stay, the higher your gratuity.' Hana'ya dürüst ödünleşimi anlatan tek bir cümle.","fa":"«⁨The longer you stay, the higher your gratuity.⁩» یک جمله که بده‌بستانِ واقعی را صادقانه به هانا می‌گوید."},"tryWhy":{"en":"many: people and family members are countable, so many. much is for money or leave.","tr":"many: kişiler ve aile üyeleri sayılabilir, bu yüzden many. much para ya da izin içindir.","fa":"جواب many است: آدم‌ها و اعضای خانواده شمارش‌پذیرند، پس many. much برای پول یا مرخصی است."},"rule":[{"en":"Grows together: the + comparative..., the + comparative.","tr":"Birlikte artan: the + karşılaştırma..., the + karşılaştırma.","fa":"وقتی دو چیز با هم رشد می‌کنند، هر دو بخش جمله با the و صفت تفضیلی شروع می‌شوند.","ex":"The longer you stay, the higher your gratuity."},{"en":"Multiples: twice / three times as ... as.","tr":"Katlar: twice / three times as ... as.","fa":"برای چند برابر، twice یا three times as ... as را به کار ببر.","ex":"twice as many people as theirs"},{"en":"many + countable, much + uncountable.","tr":"many + sayılabilen, much + sayılamayan.","fa":"many با اسم شمارش‌پذیر می‌آید و much با اسم شمارش‌ناپذیر.","ex":"twice as many days / twice as much leave"}],"test":{"en":"Does each half of the double comparative start with the? If not, add it.","tr":"Çift karşılaştırmanın her yarısı the ile mi başlıyor? Değilse ekle.","fa":"هر بخش این مقایسه‌ی دوتایی با the شروع شده؟ اگر نه، اضافه‌اش کن."},"contrast":{"en":"Persian 'harche bishtar bemani, bishtar migiri' and Turkish 'ne kadar uzun kalırsan o kadar çok' have no article, so learners write 'more you stay, more you get'. English needs the in both halves.","tr":"Türkçede 'ne kadar uzun kalırsan o kadar çok alırsın' deriz ve the gibi bir kelime yoktur; bu yüzden 'more you stay, more you get' yazılır. İngilizcede iki yarıda da the gerekir.","fa":"در فارسی می‌گوییم «هرچه بیشتر بمانی، بیشتر می‌گیری» و چیزی شبیه the نداریم؛ برای همین بعضی‌ها می‌نویسند «more you stay, more you get». در انگلیسی هر دو بخش the می‌خواهند."}},"errorWatch":[{"find":["more you stay","longer you stay, more","two times more","twice more than","as much people","as much days","as many money"],"fix":{"en":"Use 'The longer..., the more...' and 'twice as many / much as'.","tr":"'The longer..., the more...' ve 'twice as many / much as' kullan.","fa":"از «⁨The longer..., the more...⁩» و «twice as many / much as» استفاده کن."}}]},"vocab":{"id":"c-hr-6-1-v","level":"B1","category":"vocab","course":"hr","unit":"hr-6-1","goals":["career"],"title":{"en":"Pay and Benefits","tr":"Maaş ve Yan Haklar","fa":"حقوق و مزایا"},"cards":[{"word":"package","sentence":"The total package is 11,800 dirhams a month.","meaning":{"en":"Everything you get: salary, allowances and benefits.","tr":"ücret paketi.","fa":"بسته‌ی حقوق و مزایا (حقوق، کمک‌هزینه‌ها و مزایا روی هم)"}},{"word":"basic salary","sentence":"Your basic salary is 8,000 dirhams.","meaning":{"en":"The main fixed part of your pay.","tr":"temel maaş.","fa":"حقوق پایه"}},{"word":"allowance","sentence":"The housing allowance is paid every month.","meaning":{"en":"Extra money for a special purpose, like housing or transport.","tr":"yan ödeme, yardım (ör. konut yardımı, yol yardımı).","fa":"کمک‌هزینه؛ «حق» (مثل حق مسکن یا حق ایاب‌وذهاب)"}},{"word":"gross","sentence":"Gross pay is before any deductions.","meaning":{"en":"Total pay before tax or other deductions.","tr":"brüt.","fa":"ناخالص (پیش از کسر مالیات و کسورات)"}},{"word":"net","sentence":"Net pay is what arrives in your bank account.","meaning":{"en":"Pay after tax and deductions.","tr":"net.","fa":"خالص (پس از کسر مالیات و کسورات)"}},{"word":"health insurance","sentence":"Health insurance covers your partner and children.","meaning":{"en":"A plan that pays medical costs.","tr":"sağlık sigortası.","fa":"بیمه‌ی درمانی"}},{"word":"end-of-service gratuity","sentence":"In the UAE, the end-of-service gratuity is based on basic salary.","meaning":{"en":"A payment when you leave a job, based on years worked.","tr":"kıdem tazminatı.","fa":"مزایای پایان خدمت (مبلغی که هنگام ترک کار بر اساس سال‌های کار پرداخت می‌شود؛ شبیه حق سنوات در ایران)"}},{"word":"bonus","sentence":"There is an annual bonus of up to one month's basic pay.","meaning":{"en":"Extra money, often for good results.","tr":"prim, ikramiye.","fa":"پاداش (اغلب برای عملکرد خوب)"}},{"word":"payslip","sentence":"Check your payslip every month.","meaning":{"en":"A document showing your pay and deductions.","tr":"maaş bordrosu.","fa":"فیش حقوقی"}},{"word":"annual flight","sentence":"The package includes one annual flight home.","meaning":{"en":"A free ticket home once a year.","tr":"yıllık memleket bileti.","fa":"بلیت رفت‌وبرگشت سالانه به کشور خود"}}]},"story":{"id":"c-hr-6-1-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-6-1","title":{"en":"Two Offers","tr":"İki Teklif","fa":"دو پیشنهاد"},"text":"In November, Atlas created a new role in Dubai: cold-chain coordinator, for the medicine deliveries that were growing every month. Leyla thought of one name at once. Hana Yilmaz had not got the driver job in March, because Omar needed night drivers. But her details were still on file, and nobody else had four years of cold-chain experience.\n\nHana was interested. She also had another offer, from Dunes Freight.\n\n\"Theirs is 9,000 basic,\" she said on the call. \"Yours is 8,000. So theirs is better, right?\"\n\nLeyla shared the numbers. \"Let me start with the total, then the parts. Our total package is 11,800 dirhams a month. That's 8,000 basic, 3,000 housing allowance and 800 transport. Health insurance covers 80 per cent of medical costs for you and your family, and there's one flight home a year.\"\n\n\"Dunes Freight is 11,000 in total,\" Hana said slowly. \"But their insurance is only for me.\"\n\nThere was one more thing, and Leyla had to decide whether to say it. In the UAE, the end-of-service gratuity is calculated on basic salary only, not on allowances. Dunes Freight's higher basic meant a higher gratuity one day.\n\nShe said it. \"To be fair to you: their basic is higher, and the gratuity is based on basic salary. So if you stay many years, that part is better with them. Our basic rises by 5% after one year, which closes part of the gap.\"\n\nHana was quiet. \"Why are you telling me that? It's not good for you.\"\n\n\"Because you'll read your contract anyway,\" Leyla said. \"And I'd rather you join us knowing everything.\"\n\nHana asked for two days to think. On the second day, she called back with a question that started with \"If\".","vocab":[{"word":"coordinator","en":"A person who organises how people and tasks work together.","tr":"koordinatör","fa":"هماهنگ‌کننده"},{"word":"on file","en":"Kept in the company's records.","tr":"kayıtlarda","fa":"در پرونده؛ در سوابق شرکت"},{"word":"gap","en":"Here: a difference between two amounts.","tr":"fark, açık","fa":"فاصله؛ اختلاف (بین دو مبلغ)"},{"word":"calculate","en":"To work out a number.","tr":"hesaplamak","fa":"محاسبه کردن"},{"word":"I'd rather","en":"I prefer to.","tr":"tercih ederim","fa":"ترجیح می‌دهم..."}],"quiz":[{"prompt":"Why is Atlas's total package higher than Dunes Freight's?","options":["Atlas has a higher basic salary","Atlas pays bigger allowances and family insurance","Atlas pays no tax"],"correct":1},{"prompt":"Choose the correct sentence.","options":["Our basic rises with 5% after one year.","Our basic rises by 5% after one year.","Our basic rises of 5% after one year."],"correct":1},{"prompt":"What fact was not good for Atlas, but Leyla said it anyway?","options":["The gratuity is based on basic salary, which is higher at Dunes Freight","Atlas has no health insurance","The job is temporary"],"correct":0},{"prompt":"Why might Hana trust Leyla more after the call?","options":["Leyla promised more money","Leyla told her an honest fact that did not help Atlas","Leyla was in a hurry"],"correct":1}],"notice":{"en":"Hana thinks the higher basic salary is the better offer. Leyla tells her something that is not good for Atlas. Find it.","tr":"Hana daha yüksek temel maaşın daha iyi teklif olduğunu düşünüyor. Leyla ona Atlas'ın işine gelmeyen bir şey söylüyor. Bul.","fa":"هانا فکر می‌کند حقوق پایه‌ی بالاتر یعنی پیشنهاد بهتر. لیلا چیزی به او می‌گوید که به نفع اطلس نیست. پیدایش کن."},"bridge":{"en":"'Our basic rises by 5% after one year.' Next: see how by, to, per cent and a month keep numbers clear.","tr":"'Our basic rises by 5% after one year.' Sırada: by, to, per cent ve a month'un sayıları nasıl netleştirdiğini gör.","fa":"«⁨Our basic rises by 5% after one year.⁩» قدم بعد: ببین by، to، per cent و a month چطور عددها را روشن نگه می‌دارند."}},"speaking":{"id":"hr-6-1","course":"hr","unit":"hr-6-1","topic":{"en":"Explaining an Offer Package","tr":"Bir Teklif Paketini Açıklamak","fa":"توضیح بسته‌ی پیشنهادی"},"warmup":{"en":"When you compare two jobs, which number do you look at first, and why?","tr":"İki işi karşılaştırırken önce hangi sayıya bakarsın ve neden?","fa":"وقتی دو کار را با هم مقایسه می‌کنی، اول به کدام عدد نگاه می‌کنی و چرا؟"},"questions":[{"en":"Explain the package: total first, then basic, allowances and benefits.","tr":"Paketi açıkla: önce toplam, sonra temel maaş, yan ödemeler ve yan haklar.","fa":"بسته را توضیح بده: اول جمع کل، بعد حقوق پایه، کمک‌هزینه‌ها و مزایا."},{"en":"Hana asks: \"Is the housing allowance part of my gratuity?\" Answer clearly and honestly.","tr":"Hana soruyor: \"Konut yardımı kıdem tazminatıma dahil mi?\" Açık ve dürüst cevap ver.","fa":"هانا می‌پرسد: «⁨Is the housing allowance part of my gratuity?⁩» روشن و صادقانه جواب بده."},{"en":"Hana asks: \"When does my salary go up, and by how much?\" Use by and to.","tr":"Hana soruyor: \"Maaşım ne zaman ve ne kadar artıyor?\" By ve to kullan.","fa":"هانا می‌پرسد: «⁨When does my salary go up, and by how much?⁩» در جوابت از by و to استفاده کن."}],"followups":[{"en":"Explain the package in 90 seconds, then 60, then 45.","tr":"Paketi 90, sonra 60, sonra 45 saniyede açıkla.","fa":"بسته را یک بار در ۹۰ ثانیه، بعد در ۶۰ و بعد در ۴۵ ثانیه توضیح بده."},{"en":"Now describe a real package you know: pay, one benefit and how often it is paid.","tr":"Şimdi bildiğin gerçek bir ücret paketini anlat: maaş, bir yan hak ve ne sıklıkla ödendiği.","fa":"حالا یک بسته‌ی حقوقی واقعی را که می‌شناسی توصیف کن: حقوق، یکی از مزایا و اینکه هر چند وقت پرداخت می‌شود."}],"expressions":[{"phrase":"Let me start with the total, then the parts.","meaning":{"en":"Organises the numbers.","tr":"Sayıları düzenler.","fa":"عددها را مرتب و قابل فهم می‌کند."}},{"phrase":"...rises by 5% to...","meaning":{"en":"Gives the change and the new level.","tr":"Değişimi ve yeni seviyeyi verir.","fa":"مقدار تغییر و سطح جدید را می‌گوید."}},{"phrase":"To be fair to you, ...","meaning":{"en":"Introduces an honest point that may not help you.","tr":"Kendi aleyhine olabilecek dürüst bir noktayı başlatır.","fa":"نکته‌ای صادقانه را مطرح می‌کند که شاید به نفع خودت یا شرکتت نباشد."}}],"culture":{"en":"Pay is talked about differently in different places. In the UAE, packages are usually split into basic salary and allowances, there is no personal income tax, and the end-of-service gratuity is calculated on basic salary only. In the UK, people usually quote gross pay per year. In Turkey, people often talk about net pay per month. Always say which one you mean.","tr":"Maaştan farklı yerlerde farklı biçimde bahsedilir. BAE'de paketler genellikle temel maaş ve yan ödemeler olarak bölünür, kişisel gelir vergisi yoktur ve kıdem tazminatı yalnızca temel maaş üzerinden hesaplanır. Birleşik Krallık'ta insanlar genellikle yıllık brüt maaşı söyler. Türkiye'de çoğu zaman aylık net maaştan bahsedilir. Hangisini kastettiğini her zaman söyle.","fa":"در هر جای دنیا جور دیگری درباره‌ی حقوق حرف می‌زنند. در امارات، بسته معمولاً به حقوق پایه و کمک‌هزینه‌ها تقسیم می‌شود، مالیات بر درآمد شخصی وجود ندارد و مزایای پایان خدمت فقط بر اساس حقوق پایه حساب می‌شود. در بریتانیا معمولاً حقوق ناخالص سالانه را می‌گویند. در ترکیه بیشتر از حقوق خالص ماهانه حرف می‌زنند (در ایران هم معمولاً همین‌طور است). همیشه روشن کن منظورت کدام است."},"model":"Let me start with the total, then the parts. Your total package is 11,800 dirhams a month: 8,000 basic, 3,000 housing allowance and 800 for transport. Health insurance covers 80 per cent of medical costs for your family. Your basic rises by 5% to 8,400 after one year. To be fair to you, the gratuity is based on basic salary only, not on allowances.","selfCheck":[{"en":"I gave the total first, then the parts.","tr":"Önce toplamı, sonra kalemleri verdim.","fa":"اول مبلغ کل را گفتم، بعد اجزا را."},{"en":"I used by for the change and to for the new level.","tr":"Değişim için by, yeni düzey için to kullandım.","fa":"برای تغییر by و برای سطح جدید to به کار بردم."},{"en":"I said 'per cent' and 'a month' correctly.","tr":"'per cent' ve 'a month'u doğru söyledim.","fa":"«per cent» و «a month» را درست گفتم."},{"en":"I answered the gratuity question clearly and honestly.","tr":"Kıdem tazminatı sorusunu net ve dürüst cevapladım.","fa":"به سؤال مزایای پایان خدمت روشن و صادقانه جواب دادم."}]},"writing":{"id":"c-hr-6-1-w","title":{"en":"The offer summary for Hana","tr":"Hana için teklif özeti","fa":"خلاصه‌ی پیشنهاد کار برای هانا"},"course":"hr","unit":"hr-6-1","type":"writing","difficulty":"medium","prompt":{"en":"Write the offer summary email to Hana (70-100 words): the role, the total package first, then basic, allowances and benefits, the salary review with by and to, and an invitation to ask questions.","tr":"Hana'ya teklif özeti e-postasını yaz (70-100 kelime): pozisyon, önce toplam paket, sonra temel maaş, yan ödemeler ve yan haklar, by ve to ile maaş artışı ve soru sormaya davet.","fa":"ایمیل خلاصه‌ی پیشنهاد را برای هانا بنویس (۷۰ تا ۱۰۰ کلمه): عنوان شغل، اول جمع کل بسته، بعد حقوق پایه، کمک‌هزینه‌ها و مزایا، زمان و میزان افزایش حقوق با by و to و دعوت به پرسیدن سؤال."},"model":"Dear Hana, Thank you for your time today. Here is a summary of our offer for the Cold-Chain Coordinator role in Dubai. Your total package is 11,800 dirhams a month: a basic salary of 8,000 dirhams, a housing allowance of 3,000 and a transport allowance of 800. Health insurance covers 80 per cent of medical costs for you and your family, and you get one flight home a year. Your basic salary rises by 5% to 8,400 dirhams after one year. Please let me know if you have any questions. Kind regards, Leyla","frame":"Dear ___, Thank you for ___. Here is a summary of our offer for ___. Your total package is ___ a month: a basic salary of ___, ___ and ___. Health insurance covers ___ per cent of ___. Your basic salary rises by ___ to ___ after ___. Please let me know ___. Kind regards, ___","words":[{"word":"per cent"},{"word":"a month"},{"word":"rises by"}],"minWords":70,"minSentences":6,"rubric":["Task done: role, total, parts, benefits, review, invitation","Organised: total first, then parts","Language: by / to; per cent; a month","Tone: clear and honest; no hidden conditions"],"rubricI18n":{"tr":["Görev: rol, toplam, kalemler, yan haklar, gözden geçirme, davet","Düzen: önce toplam, sonra kalemler","Dil: by / to; per cent; a month","Üslup: net ve dürüst; gizli şart yok"],"fa":["کامل بودن کار: سمت، مبلغ کل، اجزا، مزایا، بازبینی حقوق، دعوت","نظم: اول مبلغ کل، بعد اجزا","زبان: by / to؛ per cent؛ a month","لحن: روشن و صادقانه؛ بدون شرط پنهان"]},"portfolio":"hr-final-4","parts":[{"t":{"en":"The role","tr":"Görev","fa":"نقش"},"find":["role"],"sample":"Cold-Chain Coordinator, Dubai"},{"t":{"en":"The total first","tr":"Önce toplam","fa":"اول جمع کل"},"find":["total package","total"],"sample":"11,800 dirhams a month"},{"t":{"en":"Basic salary and allowances","tr":"Temel maaş ve ödenekler","fa":"حقوق پایه و کمک‌هزینه‌ها"},"find":["basic salary","allowance"],"sample":"8,000 basic; 3,000 housing; 800 transport"},{"t":{"en":"The benefits","tr":"Yan haklar","fa":"مزایا"},"find":["insurance","flight"],"sample":"health insurance, 80%; one flight home a year"},{"t":{"en":"The salary review","tr":"Maaş değerlendirmesi","fa":"بازبینی حقوق"},"find":["rises by","after one year"],"sample":"basic rises by 5% to 8,400 after one year"}]},"perspective":{"id":"c-hr-6-1-p","title":{"en":"Hana with two offers","tr":"İki teklifle Hana","fa":"هانا با دو پیشنهاد"},"course":"hr","unit":"hr-6-1","type":"perspective","minSentences":3,"prompt":{"en":"You are Hana with two offers on the kitchen table. Write 3 sentences in first person: which numbers matter most to you and your family, and what did Leyla's honesty change?","tr":"Mutfak masasında iki teklifle oturan Hana'sın. Birinci tekil şahısla 3 cümle yaz: senin ve ailen için hangi sayılar en önemli ve Leyla'nın dürüstlüğü neyi değiştirdi?","fa":"تو هانا هستی و دو پیشنهاد کار روی میز آشپزخانه جلوی توست. از زبان خودت سه جمله بنویس: کدام عددها برای تو و خانواده‌ات مهم‌تر است، و صداقت لیلا چه چیزی را عوض کرد؟"}},"exit":{"id":"c-hr-6-1-x","course":"hr","unit":"hr-6-1","type":"exit","items":[{"from":"hr-6-1","kind":"blank","prompt":"Your housing allowance rises from 3,500 ___ 4,000 dirhams.","options":["to","by","at"],"correct":0,"point":2,"why":{"en":"to: 'from 3,500 to 4,000' gives the start and the new amount. 'By' would give the size of the rise (500), and 'at' doesn't pair with from.","tr":"to: 'from 3,500 to 4,000' başlangıcı ve yeni tutarı verir. 'By' artışın miktarını (500) verir; 'at' from ile eşleşmez.","fa":"to درست است، چون from 3,500 to 4,000 مبلغ شروع و مبلغ جدید را می‌گوید. by مقدار افزایش (۵۰۰) را می‌گوید و at با from جفت نمی‌شود."},"hint2":{"en":"The sentence gives the old amount and the new amount. Which word goes before the new amount?","tr":"Cümle eski miktarı ve yeni miktarı veriyor. Yeni miktardan önce hangi kelime gelir?","fa":"جمله مقدار قبلی و مقدار جدید را می‌دهد. قبل از مقدار جدید کدام کلمه می‌آید؟"}},{"from":"hr-6-1","kind":"blank","prompt":"The company pays 50 ___ of your gym membership.","options":["per cent","percents","percentage"],"correct":0,"point":2,"why":{"en":"per cent: a number + per cent, with no -s. 'Percents' is not used this way, and 'percentage' needs 'a ... of'.","tr":"per cent: sayı + per cent; -s almaz. 'Percents' bu şekilde kullanılmaz; 'percentage' 'a ... of' ister.","fa":"⁨per cent⁩ درست است: عدد و ⁨per cent⁩، بدون ⁨-s⁩. ⁨percents⁩ این‌طور به کار نمی‌رود و ⁨percentage⁩ به ساختار ⁨a ... of⁩ نیاز دارد."},"hint2":{"en":"After a number, English uses a fixed two-word form with no -s. Which option is that?","tr":"Bir sayıdan sonra İngilizce, sonunda -s olmayan iki kelimelik kalıp bir biçim kullanır. Hangi seçenek bu?","fa":"بعد از عدد، انگلیسی یک شکل ثابت دوکلمه‌ای بدون ⁨-s⁩ به کار می‌برد. کدام گزینه همین است؟"}},{"from":"hr-6-1","kind":"mcq","prompt":"Which is the clearest way to start explaining a package?","options":["Basic is 8,000, and there are some extras.","Our total package is 11,800 dirhams a month. That's 8,000 basic plus allowances.","It depends on many things."],"correct":1,"point":1,"why":{"en":"It gives the total first, then the parts, so the candidate sees the real value. Basic alone looks smaller, and 'it depends' says nothing.","tr":"Önce toplamı, sonra parçaları verir; böylece aday gerçek değeri görür. Yalnızca temel maaş daha küçük görünür; 'it depends' hiçbir şey söylemez.","fa":"اول کل بسته را می‌گوید و بعد اجزا را، تا داوطلب ارزش واقعی را ببیند. حقوق پایه به‌تنهایی کمتر به نظر می‌رسد و it depends چیزی نمی‌گوید."}},{"from":"hr-5-4","kind":"blank","prompt":"I suggest ___ Hasan as his mentor.","options":["naming","to name","name"],"correct":0,"point":2,"why":{"en":"naming: 'suggest' takes -ing. 'To name' and 'name' don't follow suggest this way.","tr":"naming: 'suggest' -ing alır. 'To name' ve 'name' suggest'ten sonra bu şekilde gelmez.","fa":"naming درست است، چون بعد از suggest فعل ing‌دار می‌آید. to name و name این‌طور بعد از suggest نمی‌آیند."}},{"from":"hr-5-2","kind":"blank","prompt":"This ___ that we lost a day.","options":["meaned","meant","meaning"],"correct":1,"point":2,"why":{"en":"meant: the past of 'mean' is meant. 'Meaned' is not a word, and 'meaning' is not a full verb.","tr":"meant: 'mean' fiilinin geçmişi meant'tir. 'Meaned' diye bir kelime yoktur; 'meaning' tam fiil değildir.","fa":"meant درست است، چون گذشته‌ی mean همان meant است. meaned وجود ندارد و meaning فعل کامل نیست."}},{"from":"hr-1-2","kind":"blank","prompt":"Could you ___ the signed contract back to me?","options":["to send","sending","send"],"correct":2,"point":2,"why":{"en":"send: 'Could you' + plain verb. 'To send' and 'sending' don't follow could.","tr":"send: 'Could you' + yalın fiil. 'To send' ve 'sending' could'dan sonra gelmez.","fa":"send درست است، چون بعد از Could you فعل ساده می‌آید. to send و sending بعد از could نمی‌آیند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
